from PIL import Image
im = Image.open('/tmp/current_ros.png')
# The checkbox is a small ~13x13 square.
# Let's find white squares
for y in range(100, 150):
    for x in range(230, 260):
        if im.getpixel((x, y))[:3] == (255, 255, 255) and im.getpixel((x-1, y))[:3] != (255, 255, 255):
            print(f'left edge at x={x}, y={y}')
" | head -n 15

